      "items": [
        {
          "id": "ex-fdmath-dilation-jacobian",
          "kind": "example",
          "domain": "mathematics",
          "title": "Dilation Jacobian and advected scalar density",
          "reference": "items/ex-fdmath-dilation-jacobian.md",
          "design_state": "Step 1 complete draft; readiness recorded separately.",
          "dependency_level": 2,
          "deps": [
            "lem-fd-transport-and-density"
          ],
          "dependency_roles": {
            "lem-fd-transport-and-density": "mathematical-premise"
          },
          "inventory_expansion_required": false,
          "statement": "Let $I\\subseteq\\mathbb R$ be an open interval containing $0$, let $U\\subseteq\\mathbb R^3$ be nonempty and open, and let $\\alpha\\in C^2(I,(0,\\infty))$ satisfy $\\alpha(0)=1$. Define the material map $\\chi(t,a)=\\alpha(t)a$ for $a\\in U$, its inverse label $A(t,x)=x/\\alpha(t)$ for $x\\in\\alpha(t)U$, the derivative matrix $F=D_a\\chi$, the Jacobian $J=\\det F$, and the Eulerian velocity $u(t,x)=\\partial_t\\chi(t,A(t,x))$. For any $\\rho_0\\in C^1(U,\\mathbb R)$ define $\\rho(t,x)=\\alpha(t)^{-3}\\rho_0(x/\\alpha(t))$. Here $C^r$ means continuous coordinate partial derivatives through total order $r$, $D_a\\chi$ is the matrix of material-coordinate partial derivatives, $D_xu$ is the matrix of spatial coordinate partial derivatives, $\\operatorname{tr}M:=\\sum_iM_{ii}$ for square matrices $M$, and $I_3$ is the $3\\times3$ identity matrix. Then\n\n$$F(t,a)=\\alpha(t)I_3,\\qquad J(t,a)=\\alpha(t)^3,\\qquad u(t,x)=\\frac{\\alpha'(t)}{\\alpha(t)}x,\\qquad \\theta(t,x):=\\operatorname{tr}(D_xu)=3\\frac{\\alpha'(t)}{\\alpha(t)},\\qquad \\rho(t,\\chi(t,a))J(t,a)=\\rho_0(a).$$\n\nThe material pullback product $\\rho(t,\\chi(t,a))J(t,a)$ is independent of time and equals $\\rho_0(a)$. This is a mathematical kinematic example, not a physical model or measurement.",
          "provenance": {
            "statement": "ai-generated",
            "proof": "ai-generated"
          },
          "sources": {
            "references": [
              {
                "title": "R. Abeyaratne, Continuum Mechanics, Volume II of Lecture Notes on the Mechanics of Solids (MIT, 1988, revised 2020), §3.4.3",
                "url": "https://web.mit.edu/abeyaratne/Volumes/RCA_Vol_II.pdf"
              }
            ],
            "scraped": []
          },
          "library": "mathematics",
          "proof_strategy": "direct",
          "generation": {
            "role": "example"
          },
          "justified_by": [],
          "aliases": [],
          "physical_scope": null,
          "empirical_premises": []
        }
      ],
