      "items": [
        {
          "id": "rem-fd-turbulence-and-closure-scope",
          "kind": "remark",
          "domain": "physics",
          "title": "Turbulent averaging and open closure questions",
          "reference": "items/rem-fd-turbulence-and-closure-scope.md",
          "design_state": "Step 1 authoring in progress; current item checkpoint recorded in batch notes.",
