        {
          "id": "post-fd-boundary-data",
          "kind": "postulate",
          "domain": "physics",
          "title": "Specified wall, thermal, periodic and initial data",
          "reference": "items/post-fd-boundary-data.md",
          "design_state": "Step 1 complete draft; readiness recorded separately.",
          "dependency_level": 2,
          "deps": [
            "def-fd-quantity-and-frame-conventions",
