          "id": "def-fd-adopted-nonnewtonian-models",
          "kind": "definition",
          "domain": "physics",
          "title": "Restricted non-Newtonian constitutive examples",
          "reference": "items/def-fd-adopted-nonnewtonian-models.md",
          "design_state": "Step 1 complete draft; readiness recorded separately.",
          "dependency_level": 3,
          "deps": [
            "post-fd-continuum-balances",
