          "id": "pthm-fd-nonnewtonian-conditional-admissibility",
          "kind": "physics-theorem",
          "domain": "physics",
          "title": "Conditional admissibility of the specified non-Newtonian branches",
          "reference": "items/pthm-fd-nonnewtonian-conditional-admissibility.md",
          "design_state": "Step 1 complete draft; readiness recorded separately.",
          "dependency_level": 4,
          "deps": [
