          "id": "def-fd-polytropic-symmetric-variables",
          "kind": "definition",
          "domain": "mathematics",
          "title": "Sound-speed variables for polytropic Euler",
          "reference": "items/def-fd-polytropic-symmetric-variables.md",
          "design_state": "Step 1 complete draft; conditional interfaces and source scope are recorded in batch-18 notes.",
          "dependency_level": 1,
          "deps": [
            "def-fd-periodic-fourier-sobolev-spaces",
