        {
          "id": "lem-fd-polynomial-ode-continuation",
          "kind": "lemma",
          "domain": "mathematics",
          "title": "Continuation of bounded polynomial ODE solutions",
          "reference": "items/lem-fd-polynomial-ode-continuation.md",
          "design_state": "Step 1 local A-page supplier added to close an explicitly identified prerequisite gap; complete carrier authored.",
          "dependency_level": 0,
          "deps": [
